#!/usr/bin/env python3
"""Supplementary real clicks for creative asset updates/removal and key editing."""
import argparse,json,time
from pathlib import Path
from check_gui_buttons import Audit

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--url',required=True);p.add_argument('--out',type=Path,required=True);p.add_argument('--webdriver',default='http://127.0.0.1:9519');a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True);t=Audit(a)
    def wait_done(id):t.wait('return !'+id+'.disabled')
    try:
        assert not t.api('state')['connection']['enabled']
        t.api('harness/tool',{'name':'run_recipe','arguments':{'mode':'replace','baseRevision':t.rev(),'code':"mf.box([0,0,0],[4,8,2],{style:2,group:'door'});mf.triangle([8,0,0],[12,0,0],[8,5,0],{color:'#88ABEE',group:'flag'});"}});t.wait('return window.__morphforge.state.stats.groups.flag===1');revision=t.rev()
        t.click('comparisonOpen');t.click('comparisonFromMain');t.click('comparisonSide');t.fill('comparisonName','侧面对照',False);t.click('comparisonSave');t.wait('return comparisonBookmark.value!==""&&!comparisonSave.disabled');id=t.js('return comparisonBookmark.value');t.check('side camera button saves a real side-facing camera',t.api('creative')['bookmarks'][id]['shot']['position'][0]>0);t.click('comparisonRemove');t.wait('return !comparisonRemove.disabled&&comparisonBookmark.value===""');t.check('remove bookmark leaves the scene untouched',id not in t.api('creative')['bookmarks'] and t.rev()==revision);t.click('comparisonClose')
        t.click('componentOpen');t.fill('componentGroups','door',False);t.fill('componentName','可更新组件',False);t.click('componentSave');t.wait('return componentSelect.value!==""&&!componentSave.disabled');id=t.js('return componentSelect.value');t.fill('componentGroups','flag',False);t.click('componentReplace');wait_done('componentReplace');t.check('replace component updates the same named asset from triangle source',len(t.api('creative/components',{'action':'inspect','id':id})['component']['scene']['triangles'])==1);t.click('componentRemove');wait_done('componentRemove');t.wait('return componentStatus.textContent.includes("请选择")');t.check('remove component clears stale preview and retains geometry',not any(c['id']==id for c in t.api('creative')['components']) and t.rev()==revision);t.click('componentClose')
        t.click('animationOpen');t.click('motionNew');t.fill('motionGroup','door');t.fill('motionTime',1);t.check('empty timeline can be positioned before its first key',t.js('return motionTimeLabel.textContent.includes("1.00")'));t.fill('motionScale','0, 1, 1',False);t.click('motionAddKey');wait_done('motionAddKey');t.check('invalid key does not leave a broken empty track',t.js('return window.__morphforge.creative.clip.tracks.length===0') and t.feedback());t.fill('motionScale','1, 1, 1',False);t.click('motionPivotCenter');t.check('pivot-center button uses actual group bounds',t.js('return motionPivot.value==="2, 0, 1"'));t.fill('motionTime',0);t.click('motionAddKey');t.fill('motionTime',2);t.fill('motionRotation','0, 90, 0',False);t.click('motionAddKey');t.fill('motionTime',1);t.check('scrubbing updates editable fields to the visible interpolated pose',abs(float(t.js('return motionRotation.value.split(",")[1]'))-45)<1e-4);t.click('motionAddKey');t.check('inserting a key preserves the viewed pose',t.js('return window.__morphforge.creative.clip.tracks[0].keys.length===3&&Math.abs(window.__morphforge.creative.clip.tracks[0].keys[1].rotation[1]-45)<.001'));t.click('#motionKeys .row:nth-child(2) button:last-child');t.check('key delete removes exactly the selected key',t.js('return window.__morphforge.creative.clip.tracks[0].keys.length===2'));t.click('motionStart');t.check('return-to-start moves visible cursor and editor values together',t.js('return motionTime.value==="0"&&motionRotation.value==="0, 0, 0"'));t.click('motionDeleteTrack');t.check('track delete restores static rendering',t.js('return window.__morphforge.creative.clip.tracks.length===0&&!window.__morphforge.renderer.animationClip'));t.fill('motionGroup','flag');t.fill('motionTime',0);t.click('motionAddKey');t.fill('motionName','可删除动画',False);t.click('motionSave');t.wait('return motionClip.value!==""&&!motionSave.disabled');id=t.js('return motionClip.value');t.click('motionNew');t.check('new animation clears unsaved track selection',t.js('return motionClip.value===""&&window.__morphforge.creative.clip.tracks.length===0'));t.fill('motionClip',id);t.click('motionRemove');t.wait('return !motionRemove.disabled&&motionClip.value===""');t.check('remove animation persists and returns to a fresh draft',id not in t.api('creative')['clips'] and t.rev()==revision);t.click('motionClose');t.check('supplementary controls have no unhandled errors',not t.js('return window.__guiAuditErrors'));t.b.screenshot(a.out/'controls.png')
    except Exception as e:t.failures.append({'case':'creative supplementary buttons','error':str(e)});t.b.screenshot(a.out/'failure.png');raise
    finally:(a.out/'validation.json').write_text(json.dumps(t.result(),ensure_ascii=False,indent=2)+'\n');t.b.close()
if __name__=='__main__':main()
